package com.greenocean.backend;
import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import org.junit.jupiter.api.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(properties={"greenocean.clinic.commerce-enabled=true","greenocean.clinic.records-enabled=true","greenocean.clinic.record-keys=clinical-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.record-current-key=clinical-qa","greenocean.clinic.reputation-enabled=true","greenocean.clinic.public-reputation-enabled=true","greenocean.clinic.reputation-keys=reputation-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.reputation-current-key=reputation-qa"})@AutoConfigureMockMvc@ActiveProfiles("test")@Transactional
class PhaseQ3RankingFairnessTest extends PhaseP4Fixtures {
 @Test void fourDistinctPatientsRemainBelowMinimumWithoutInventedClinicalScore(){distinctPatients(4);assertThat(ownRank()).containsEntry("experienceIndicator",null).containsEntry("verifiedPatientCount",null).containsEntry("sampleBand","INSUFFICIENT_EVIDENCE");}
 @Test void largerCohortProducesBoundedExperienceIndicatorWithoutClinicalOutcomeClaim(){distinctPatients(12);var rank=ownRank();assertThat(rank).containsEntry("verifiedPatientCount",12);assertThat((Double)rank.get("experienceIndicator")).isBetween(0.0,95.0);assertThat(rank).doesNotContainKeys("diagnosis","patient_id","revenue","clinicalOutcome");}
 @Test void audioHistoryDoesNotBecomeFiveTextModeVotes(){for(int n=1;n<=5;n++){var patient=PhaseIFixtures.member(db,users,tokens);var feedback=reputation.feedback(patient.id(),input(historical(patient,n,true,"AUDIO"),5,true,false));approve(feedback);}assertThat(ownRank()).containsEntry("experienceIndicator",null).containsEntry("sampleBand","INSUFFICIENT_EVIDENCE");}
 @Test void shortTermInactivityDoesNotFabricateLossOfProfessionalQualification(){distinctPatients(5);db.update("UPDATE clinic_feedback SET updated_at=CURRENT_TIMESTAMP-INTERVAL '14 days' WHERE professional_id=?",author.id());var rank=ownRank();assertThat(rank).containsEntry("verifiedPatientCount",5);assertThat((Double)rank.get("experienceIndicator")).isBetween(0.0,95.0);assertThat(rank.get("professionalId")).isEqualTo(author.id());}
}
